+        m_pAclOrch->m_routeOrch->decreaseNextHopRefCount(target, __PRETTY_FUNCTION__, __LINE__, "");
         // remove next hop group in case it's not used by anything else
         if (m_pAclOrch->m_routeOrch->isRefCounterZero(target))
         {
