         }
@@ -1191,7 +1191,7 @@ bool FgNhgOrch::removeRoute(sai_object_id_t vrf_id, const IpPrefix &ipPrefix)
 
     for (auto nh : syncd_fg_route_entry->active_nexthops)
     {
-        m_neighOrch->decreaseNextHopRefCount(nh);
+        m_neighOrch->decreaseNextHopRefCount(nh, __PRETTY_FUNCTION__, __LINE__, ipPrefix.to_string());
     }
 
     // remove state_db entry
@@ -1326,7 +1326,7 @@ bool FgNhgOrch::doTaskFgNhg(const KeyOpFieldsValuesTuple & t)
             }
             else
             {
-                SWSS_LOG_INFO("Child Prefix/Member entries are still associated with this FG_NHG %s", 
+                SWSS_LOG_NOTICE("Child Prefix/Member entries are still associated with this FG_NHG %s", 
                         fg_nhg_name.c_str());
                 return false;
             }
